// What every world (the sheet, the map, the book) offers the stage.
import type * as THREE from "three";
import type { ChapterKey } from "./chapters.ts";
import type { WorldId } from "./mix.ts";
import type { Person, Project } from "./person.ts";
import type { Land } from "./land.ts";
import type { Palette } from "./look.ts";

/** `words` are the person's own words for any chapter, which a world that prints a chapter's words uses in place of its own. */
export type WorldEnv = { person: Person; palette: Palette; words: Partial<Record<ChapterKey, string>>; renderer: THREE.WebGLRenderer; land: Land; narrow: () => boolean };

/** Where the story stands inside one world: chapter keys, the eased move t, its raw share, the hold's share and the clock. */
export type WorldView = { from: ChapterKey; to: ChapterKey; t: number; raw: number; local: number; time: number };

/**
 * The element a dive's card stands on: the middle of its face, which way it
 * faces (+z, with +y its up), and its size. The card is fitted inside it,
 * centred, or with `rest` standing on its lower edge.
 */
export type Anchor = { position: THREE.Vector3; quaternion: THREE.Quaternion; size: { w: number; h: number }; rest?: boolean };

export interface World {
  readonly id: WorldId;
  /** Has an opaque background of its own. */
  readonly scene: THREE.Scene;
  readonly camera: THREE.PerspectiveCamera;
  /** Stateless: the same view always gives the same picture. */
  pose(view: WorldView): void;
  /** The element a card showing the next world stands on, at that chapter's hold. */
  anchor(chapter: ChapterKey): Anchor;
  /** The project under a point on the screen (-1 to 1 each way) while a chapter holds. */
  pick(ndc: THREE.Vector2, chapter: ChapterKey): Project | null;
  resize(aspect: number): void;
  dispose(): void;
}

export type WorldFactory = (env: WorldEnv, chapters: ChapterKey[]) => Promise<World>;

/** A view that holds a chapter. */
export const holding = (key: ChapterKey, local: number, time = 0): WorldView => ({ from: key, to: key, t: 0, raw: 0, local, time });
/* A stitched story. Everything sits under .stitch, so a page can hold other things. */
.stitch {
  /* Night's colours; StitchedStory sets the look's own (look.ts). */
  --st-bg: #0f1318; --st-ink: #ece6d9; --st-soft: #c9cfd5; --st-muted: #9aa4ae; --st-amber: #e9a23b;
  --st-line: rgba(236, 230, 217, 0.14); --st-glass: rgba(12, 16, 21, 0.72); --st-on-ink: #11161c;
  --st-serif: Georgia, "Times New Roman", serif; --st-sans: system-ui, sans-serif;
  position: relative; color: var(--st-ink); background: var(--st-bg); font-family: var(--st-sans);
  -webkit-font-smoothing: antialiased; min-height: 100vh;
}
.stitch a { color: inherit; }
.stitch .gl { position: fixed; inset: 0; width: 100%; height: 100%; display: block; z-index: 0; }
.stitch .spacer { position: relative; z-index: -1; }

.stitch .ui { position: fixed; inset: 0; pointer-events: none; z-index: 2; }
.stitch .rail { position: absolute; right: 18px; top: 50%; transform: translateY(-50%); display: flex; flex-direction: column; gap: 6px; }
.stitch .rail button { pointer-events: auto; display: flex; align-items: center; justify-content: flex-end; gap: 10px; background: none; border: 0;
  color: var(--st-muted); font: 500 13px var(--st-sans); cursor: pointer; padding: 3px 0; flex-direction: row-reverse; }
/* A halo in the caption glass's colour keeps the rail and hint readable over any world, such as the book's dark desk in a light look. */
.stitch .rail button, .stitch .hint { text-shadow: 0 0 3px var(--st-glass), 0 0 8px var(--st-glass), 0 0 14px var(--st-glass); }
.stitch .rail i { width: 7px; height: 7px; border-radius: 50%; background: currentColor; opacity: 0.5; box-shadow: 0 0 0 2px var(--st-glass); }
.stitch .rail button.on { color: var(--st-ink); }
.stitch .rail button.on i { background: var(--st-amber); opacity: 1; transform: scale(1.4); }
.stitch .cap { position: absolute; left: 24px; bottom: 28px; max-width: 430px; padding: 18px 20px; border-radius: 14px;
  background: var(--st-glass); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); border: 1px solid var(--st-line); }
.stitch .cap .num { color: var(--st-amber); font: 600 12px var(--st-sans); letter-spacing: 0.12em; }
.stitch .cap h2 { font-family: var(--st-serif); font-weight: 600; font-size: 26px; margin: 4px 0 6px; }
.stitch .cap p { margin: 0; color: var(--st-soft); line-height: 1.5; font-size: 15px; }
.stitch .hint { position: absolute; bottom: 26px; left: 50%; transform: translateX(-50%); color: var(--st-muted); font-size: 13px; letter-spacing: 0.1em;
  text-transform: uppercase; transition: opacity 0.4s; }
.stitch.nowords .cap, .stitch.nowords .rail span, .stitch.nowords .hint { display: none; }
/* In the book the left page carries the chapter's words. */
.stitch .cap.inbook { display: none; }

.stitch .cta { position: fixed; z-index: 3; left: 50%; bottom: 34px; transform: translateX(-50%); display: flex; gap: 10px; opacity: 0; pointer-events: none; }
.stitch .cta a { border-radius: 999px; padding: 12px 20px; font: 600 15px var(--st-sans); text-decoration: none; background: var(--st-amber); color: #11161c; white-space: nowrap; }
.stitch .cta a + a { background: var(--st-ink); color: var(--st-on-ink); }

.stitch .modal { position: fixed; inset: 0; z-index: 10; background: rgba(5, 7, 10, 0.6); display: grid; place-items: center; padding: 16px; }
.stitch .modal .sheet { position: relative; width: min(620px, 100%); max-height: calc(100vh - 32px); overflow: auto; background: #f2ede2; color: #1c222a; border-radius: 16px; }
.stitch .modal .pic canvas { width: 100%; display: block; }
.stitch .modal .body { padding: 20px 24px 26px; }
.stitch .modal .eyebrow { color: #b47718; font: 600 12px var(--st-sans); letter-spacing: 0.12em; text-transform: uppercase; }
.stitch .modal h3 { font-family: var(--st-serif); font-size: 30px; margin: 6px 0 8px; }
.stitch .modal p { margin: 0 0 10px; line-height: 1.55; }
.stitch .modal .more { color: #6d7782; font-size: 14px; }
.stitch .modal .tags span { display: inline-block; border: 1px solid #c9c1b0; border-radius: 999px; padding: 4px 10px; font-size: 13px; margin: 0 6px 6px 0; }
.stitch .modal [data-close] { position: absolute; top: 10px; right: 12px; border: 0; background: rgba(255, 255, 255, 0.8); border-radius: 50%;
  width: 34px; height: 34px; font-size: 22px; line-height: 1; cursor: pointer; color: #1c222a; }

/* The words in full: on the page without the 3D, for screen readers only with it. */
.stitch .text { position: relative; z-index: 1; max-width: 680px; margin: 0 auto; padding: 48px 20px 80px; line-height: 1.55; }
.stitch .text h1 { font-family: var(--st-serif); font-size: 40px; margin: 0 0 24px; }
.stitch .text h2 { font-family: var(--st-serif); font-size: 24px; margin: 28px 0 6px; }
.stitch[data-scene="on"] .text, .stitch[data-scene="wait"] .text {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.stitch[data-scene="off"] .gl, .stitch[data-scene="off"] .ui, .stitch[data-scene="off"] .cta, .stitch[data-scene="off"] .spacer { display: none; }

@media (max-width: 720px) {
  .stitch .rail span { display: none; }
  .stitch .rail { right: 8px; }
  .stitch .cap { left: 12px; right: 12px; bottom: 14px; max-width: none; padding: 12px 14px; }
  .stitch .cap h2 { font-size: 20px; margin: 2px 0 4px; }
  .stitch .cap p { font-size: 14px; line-height: 1.4; }
  .stitch .cta { bottom: 22px; }
}
@media (scripting: none) {
  .stitch .text { position: relative !important; width: auto !important; height: auto !important; margin: 0 auto !important; padding: 48px 20px 80px !important;
    overflow: visible !important; clip: auto !important; white-space: normal !important; }
  .stitch .gl, .stitch .ui, .stitch .cta { display: none; }
}

